using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    private static int ChargedFor(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged the subtotal less the Bronze reduction
    [Theory]
    [InlineData(10000, 9500)]
    [InlineData(7, 7)]
    public void S1_BronzeCustomerIsChargedSubtotalLessBronzeReduction(int subtotalCents, int expectedTotalCents)
    {
        Assert.Equal(expectedTotalCents, ChargedFor(LoyaltyTier.Bronze, subtotalCents));
    }

    // Silver customer is charged the subtotal less the Silver reduction
    [Fact]
    public void S2_SilverCustomerIsChargedSubtotalLessSilverReduction()
    {
        Assert.Equal(9000, ChargedFor(LoyaltyTier.Silver, 10000));
    }

    // Gold customer is charged the subtotal less the Gold reduction
    [Fact]
    public void S3_GoldCustomerIsChargedSubtotalLessGoldReduction()
    {
        Assert.Equal(8500, ChargedFor(LoyaltyTier.Gold, 10000));
    }
}

